-- 10_insertion_periode_7.sql - Portrait de l'Âme (Périodes 7A et 7B)
-- DERNIER SCRIPT + VÉRIFICATION FINALE
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO cycle_vie_soul_periods (
    period_number, polarity, date_start, date_end, period_name, period_title,
    description_general, traits_positifs, traits_vigilance, professions_favorables,
    sante_vigilance, pays_affinites, conseils, message_cosmique, is_active
) VALUES 
-- PÉRIODE 7A
(7, 'A', '09-23', '10-22', 'Les Humanistes', 'L''Âme Humaniste Visionnaire',
E'Vous êtes unique parmi toutes les âmes, car vous représentez un mélange de tous les types planétaires et par conséquent de toutes les caractéristiques, tendances et qualités.\n\nCette universalité vous rend difficile à classer, mais elle vous donne aussi une compréhension profonde de la nature humaine dans toutes ses manifestations. Vous êtes véritablement citoyen(ne) du monde.\n\nVous êtes naturellement humanitaire et universaliste dans votre point de vue et vos philosophies. Vous croyez en la valeur de l''Homme — non pas d''un peuple, d''une race ou d''une nation particulière, mais de l''Homme en tant qu''entité cosmique.',
E'**La Vision Universelle**\nVous voyez au-delà des frontières et des divisions. Cette perspective globale vous permet de trouver des solutions.\n\n**L''Empathie Profonde**\nVous ressentez intuitivement ce que vivent les autres, quelle que soit leur origine.\n\n**L''Idéalisme Pratique**\nVos grands idéaux sont toujours accompagnés de plans concrets.\n\n**La Polyvalence Naturelle**\nVous vous adaptez à n''importe quel environnement, culture ou situation.',
E'**La Dispersion Énergétique**\nVotre intérêt pour tout peut vous empêcher de vous concentrer sur quelque chose.\n\n**L''Idéalisme Déçu**\nFace à la réalité du monde, votre foi en l''humanité peut vaciller.\n\n**L''Inconstance Apparente**\nLes autres peuvent vous percevoir comme changeant(e) ou peu fiable.',
E'**Les Métiers de l''Humanitaire**\n• Directeur(trice) d''organisation internationale\n• Diplomate ou négociateur(trice) de paix\n• Travailleur(se) humanitaire\n• Défenseur(se) des droits humains\n\n**Les Métiers de la Vision**\n• Futuriste ou prospectiviste\n• Penseur(se) ou philosophe\n• Inventeur(trice) social(e)\n• Écrivain(e) ou conférencier(ère)',
E'• Problèmes circulatoires (jambes et chevilles)\n• Affections nerveuses dues à la surcharge mentale\n• Sensibilité aux ondes et aux environnements\n• États d''épuisement liés au don de soi excessif',
E'Votre âme résonne avec le monde entier, mais particulièrement avec :\n• L''Angleterre et l''Allemagne (aspects cosmopolites)\n• Les grandes métropoles internationales\n• Les lieux de rencontre des cultures',
E'1. **Choisissez Un Combat Principal** — Vous ne pouvez pas sauver tout le monde en même temps.\n2. **Ancrez-Vous dans le Concret** — Les grandes visions ont besoin de petites actions.\n3. **Protégez Votre Énergie** — L''empathie excessive peut vous vider.\n4. **Entourez-Vous de Réalistes** — Ils vous aideront à garder les pieds sur terre.',
E'Vous êtes venu(e) dans cette vie pour être un pont entre les mondes, un ambassadeur de l''unité humaine. Votre vision d''une humanité réconciliée n''est pas une utopie — c''est une destination vers laquelle vous guidez les autres. Gardez foi en cette mission, même quand le chemin semble long.',
true),

-- PÉRIODE 7B
(7, 'B', '09-23', '10-22', 'Les Mystiques', 'L''Âme Mystique Intuitive',
E'En plus des caractéristiques universelles de votre groupe cosmique, vous êtes très mystique et un(e) excellent(e) étudiant(e) des sciences et arts mystiques ou occultes.\n\nVos incarnations passées vous ont conduit(e) dans les écoles de mystères et les temples secrets. Vous possédez une excellente perception intuitive et psychique.\n\nSi vous suivez votre illumination intérieure et votre guidance intuitive, vous pouvez accomplir de grandes choses dans les domaines inhabituels de recherche ou d''activité. Votre monde intérieur est aussi réel — sinon plus — que le monde extérieur.',
E'**L''Intuition Profonde**\nVous percevez ce qui échappe aux autres. Cette voyance naturelle vous guide.\n\n**La Compréhension des Mystères**\nLes sujets complexes et ésotériques vous paraissent naturels et accessibles.\n\n**La Protection Psychique**\nVotre sensibilité aiguisée vous permet de vous protéger des influences négatives.\n\n**La Sagesse Universelle**\nVous avez accès à une forme de connaissance qui dépasse l''apprentissage ordinaire.',
E'**La Sensibilité Excessive**\nVotre réceptivité peut parfois vous submerger. Apprenez à filtrer.\n\n**L''Isolement Mystique**\nVotre monde intérieur riche peut vous éloigner des réalités pratiques.\n\n**La Confusion des Plans**\nDistinguer intuition vraie et imagination est un apprentissage constant.',
E'**Les Métiers de la Guidance**\n• Conseiller(ère) spirituel(le) ou coach de vie\n• Thérapeute holistique\n• Médiateur(trice) ou accompagnant(e)\n• Formateur(trice) en développement personnel\n\n**Les Métiers de la Création Intuitive**\n• Artiste inspiré(e)\n• Écrivain(e) de fiction ou de spiritualité\n• Chercheur(se) en domaines frontières\n• Musicien(ne) ou compositeur(trice)',
E'• Problèmes circulatoires\n• Affections nerveuses\n• Sensibilité aux environnements (bruit, foules)\n• Besoin impératif de temps de solitude et de ressourcement',
E'Comme vos proches cosmiques universels, avec affinité pour :\n• Les lieux de pèlerinage et de méditation\n• Les sites sacrés antiques\n• Les montagnes et les déserts propices à la contemplation',
E'1. **Honorez Votre Nature Mystique** — Elle n''est ni anormale ni impraticable, elle est votre force.\n2. **Développez des Pratiques de Protection** — La méditation, l''ancrage, la visualisation.\n3. **Gardez un Pied dans le Monde Matériel** — L''équilibre entre les deux mondes est essentiel.\n4. **Trouvez Votre Communauté** — D''autres âmes comme la vôtre existent et peuvent vous comprendre.',
E'Vous êtes venu(e) dans cette vie pour être un pont entre le visible et l''invisible. Vos dons de perception sont précieux dans un monde qui a oublié les dimensions cachées de l''existence. Utilisez-les avec sagesse, humilité et amour.',
true);

SELECT '✅ PÉRIODE 7 (7A + 7B) INSÉRÉE' as status;

-- ═══════════════════════════════════════════════════════════════════════════
-- VÉRIFICATION FINALE - TOUTES LES 14 PÉRIODES
-- ═══════════════════════════════════════════════════════════════════════════
SELECT '═══════════════════════════════════════════════════════════════════════════' as separator;
SELECT '🎉 VÉRIFICATION FINALE - TOUTES LES PÉRIODES' as status;
SELECT '═══════════════════════════════════════════════════════════════════════════' as separator;

SELECT 
    period_number || polarity AS periode,
    period_name,
    LENGTH(description_general) as desc_len,
    LENGTH(traits_positifs) as forces_len,
    LENGTH(traits_vigilance) as defis_len,
    LENGTH(professions_favorables) as vocations_len,
    LENGTH(sante_vigilance) as sante_len,
    LENGTH(pays_affinites) as geo_len,
    LENGTH(conseils) as conseils_len,
    LENGTH(message_cosmique) as msg_len
FROM cycle_vie_soul_periods
ORDER BY period_number, polarity;

SELECT 'TOTAL: ' || COUNT(*) || ' périodes insérées' as resume FROM cycle_vie_soul_periods;
